import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { privatePath } from '@puddle/shared/node';
import { runtimeLaunchSchema } from '@puddle/shared';
import { readRuntimeJson } from './storage.js';
import { installShellHooks, ShellHooks } from '../pty/shell-hooks.js';

const files = ['.zshenv', '.zprofile', '.zshrc', '.zlogin', 'env-report.zsh'];

/** Written once before dispatch, never regenerated by a later daemon build. */
export function pinRuntimeShellHooks(directory: string): ShellHooks {
  const shellHooksDir = join(directory, 'shell-hooks');
  if (existsSync(shellHooksDir)) throw new Error('Runtime shell hooks already exist');
  return installShellHooks({ shellHooksDir });
}

/** Older experimental owners may lack hooks; an incomplete pinned tree is an error. */
export function readRuntimeShellHooks(directory: string): ShellHooks | null {
  const root = join(directory, 'shell-hooks');
  if (!existsSync(root)) {
    if (runtimeLaunchSchema.parse(readRuntimeJson(join(directory, 'launch.json'))).shell_hooks)
      throw new Error('Pinned runtime shell hooks are missing');
    return null;
  }
  privatePath(root, true);
  const zsh = join(root, 'zsh');
  const bash = join(root, 'bash');
  privatePath(zsh, true);
  privatePath(bash, true);
  for (const file of files) privatePath(join(zsh, file));
  const rc = join(bash, 'bashrc.bash');
  privatePath(rc);
  return new ShellHooks(zsh, rc);
}
